from pathlib import Path
import json

ROOT = Path('.')

def edit(path, fn):
    p = ROOT / path
    s = p.read_text()
    n = fn(s)
    if n == s:
        raise SystemExit(f'no change made: {path}')
    p.write_text(n)

# Version
edit('package.json', lambda s: s.replace('"version": "1.100.35"', '"version": "1.101.0"', 1))
edit('public/data/version.json', lambda s: json.dumps({'version':'1.101.0'}, ensure_ascii=False, indent=2)+'\n')

